<?php
namespace RoutesPro\Services;

use RoutesPro\Core\AuditLog;
use RoutesPro\Forms\RecordService;
use RoutesPro\Support\Permissions;
use WP_Error;

if (!defined('ABSPATH')) exit;

/**
 * Controlled removal of operational test/history data generated by one user.
 *
 * Deliberately preserves master data, store profiles, clients, projects,
 * commercial assignments, expenses, audit/security history and Cloud ledgers.
 */
final class UserOperationalPurgeService {
    public const VERSION = '1.0.0';
    private const MAX_ROUTES = 5000;
    private const MAX_SUBMISSIONS = 20000;
    private const MAX_VERSIONS = 40000;

    public static function preview(int $userId, string $dateFrom = '', string $dateTo = '') {
        global $wpdb;
        $userId = absint($userId);
        if ($userId <= 0 || !get_userdata($userId)) {
            return new WP_Error('fieldflow_purge_user_invalid', 'Seleciona um utilizador válido.', ['status'=>400]);
        }
        $range = self::normaliseRange($dateFrom, $dateTo);
        if (is_wp_error($range)) return $range;

        $px = $wpdb->prefix . 'routespro_';
        foreach (['routes','route_stops','assignments','form_submissions','form_submission_answers','form_record_versions','form_record_values','form_records','events'] as $suffix) {
            if (!self::tableExists($px . $suffix)) {
                return new WP_Error('fieldflow_purge_schema_missing', 'A purga foi bloqueada porque a tabela ' . $suffix . ' não está disponível.', ['status'=>503]);
            }
        }

        $routeWhere = ['owner_user_id=%d'];
        $routeArgs = [$userId];
        self::appendDateRange($routeWhere, $routeArgs, 'date', $range);
        $routeRows = $wpdb->get_results($wpdb->prepare(
            "SELECT id,client_id,project_id,date,status,owner_user_id FROM {$px}routes WHERE " . implode(' AND ', $routeWhere) . ' ORDER BY id ASC LIMIT ' . (self::MAX_ROUTES + 1),
            ...$routeArgs
        ), ARRAY_A) ?: [];
        $routeOverflow = count($routeRows) > self::MAX_ROUTES;
        if ($routeOverflow) $routeRows = array_slice($routeRows, 0, self::MAX_ROUTES);
        $routeIds = self::ids($routeRows, 'id');

        $stopRows = [];
        if ($routeIds) {
            $stopRows = $wpdb->get_results("SELECT id,route_id,location_id,status,arrived_at,departed_at FROM {$px}route_stops WHERE route_id IN (" . self::idList($routeIds) . ') ORDER BY id ASC', ARRAY_A) ?: [];
        }
        $stopIds = self::ids($stopRows, 'id');

        // Recover orphan stop residues from routes that may already have been
        // manually removed. We only accept stops proven by this user's event
        // history and whose parent route no longer exists, so shared live route
        // plans are never removed through this recovery path.
        $eventSeedWhere = ['e.user_id=%d'];
        $eventSeedArgs = [$userId];
        self::appendDateRange($eventSeedWhere, $eventSeedArgs, 'DATE(e.created_at)', $range);
        $eventSeedStopIds = self::columnIds($wpdb->get_col($wpdb->prepare(
            "SELECT DISTINCT e.route_stop_id FROM {$px}events e WHERE " . implode(' AND ', $eventSeedWhere) . ' ORDER BY e.route_stop_id ASC',
            ...$eventSeedArgs
        )) ?: []);
        $missingSeedStopIds = array_values(array_diff($eventSeedStopIds, $stopIds));
        if ($missingSeedStopIds) {
            $orphanStopRows = $wpdb->get_results(
                "SELECT rs.id,rs.route_id,rs.location_id,rs.status,rs.arrived_at,rs.departed_at FROM {$px}route_stops rs LEFT JOIN {$px}routes r ON r.id=rs.route_id WHERE rs.id IN (" . self::idList($missingSeedStopIds) . ') AND r.id IS NULL ORDER BY rs.id ASC',
                ARRAY_A
            ) ?: [];
            if ($orphanStopRows) {
                $stopRows = array_merge($stopRows, $orphanStopRows);
                $stopIds = self::ids($stopRows, 'id');
            }
        }

        // A submission can belong to the user directly, to one of their routes,
        // or to one of the route stops even if a previous manual edit cleared user_id.
        $submissionParts = ['s.user_id=%d'];
        $submissionArgs = [$userId];
        if ($routeIds) $submissionParts[] = 's.route_id IN (' . self::idList($routeIds) . ')';
        if ($stopIds) $submissionParts[] = 's.route_stop_id IN (' . self::idList($stopIds) . ')';
        $submissionWhere = ['(' . implode(' OR ', $submissionParts) . ')'];
        self::appendDateRange($submissionWhere, $submissionArgs, 'COALESCE(s.report_day,DATE(s.submitted_at))', $range);
        $submissionRows = $wpdb->get_results($wpdb->prepare(
            "SELECT s.id,s.form_id,s.user_id,s.client_id,s.project_id,s.route_id,s.route_stop_id,s.location_id,s.report_day,s.submitted_at,s.status,s.record_id,s.record_version_id FROM {$px}form_submissions s WHERE " . implode(' AND ', $submissionWhere) . ' ORDER BY s.id ASC LIMIT ' . (self::MAX_SUBMISSIONS + 1),
            ...$submissionArgs
        ), ARRAY_A) ?: [];
        $submissionOverflow = count($submissionRows) > self::MAX_SUBMISSIONS;
        if ($submissionOverflow) $submissionRows = array_slice($submissionRows, 0, self::MAX_SUBMISSIONS);
        $submissionIds = self::ids($submissionRows, 'id');

        // Include historical versions attributed to this operative, including
        // residues whose primary submission was manually removed in older flows.
        $versionParts = ['v.user_id=%d', 'v.owner_user_id=%d'];
        $versionArgs = [$userId, $userId];
        if ($submissionIds) $versionParts[] = 'v.submission_id IN (' . self::idList($submissionIds) . ')';
        if ($routeIds) $versionParts[] = 'v.route_id IN (' . self::idList($routeIds) . ')';
        if ($stopIds) $versionParts[] = 'v.route_stop_id IN (' . self::idList($stopIds) . ')';
        $versionWhere = ['(' . implode(' OR ', $versionParts) . ')'];
        self::appendDateRange($versionWhere, $versionArgs, 'DATE(v.submitted_at)', $range);
        $versionRows = $wpdb->get_results($wpdb->prepare(
            "SELECT v.id,v.record_id,v.submission_id,v.route_id,v.route_stop_id,v.user_id,v.owner_user_id,v.submitted_at FROM {$px}form_record_versions v WHERE " . implode(' AND ', $versionWhere) . ' ORDER BY v.id ASC LIMIT ' . (self::MAX_VERSIONS + 1),
            ...$versionArgs
        ), ARRAY_A) ?: [];
        $versionOverflow = count($versionRows) > self::MAX_VERSIONS;
        if ($versionOverflow) $versionRows = array_slice($versionRows, 0, self::MAX_VERSIONS);

        // If a version still points to a live submission, include that submission
        // in the purge so the analytics and operational layers stay coherent.
        $versionSubmissionIds = array_values(array_unique(array_filter(array_map(static fn(array $row): int => absint($row['submission_id'] ?? 0), $versionRows))));
        $missingSubmissionIds = array_values(array_diff($versionSubmissionIds, $submissionIds));
        if ($missingSubmissionIds) {
            $extraRows = $wpdb->get_results("SELECT s.id,s.form_id,s.user_id,s.client_id,s.project_id,s.route_id,s.route_stop_id,s.location_id,s.report_day,s.submitted_at,s.status,s.record_id,s.record_version_id FROM {$px}form_submissions s WHERE s.id IN (" . self::idList($missingSubmissionIds) . ') ORDER BY s.id ASC', ARRAY_A) ?: [];
            foreach ($extraRows as $row) $submissionRows[] = $row;
            $submissionIds = self::ids($submissionRows, 'id');
        }

        $versionIds = self::ids($versionRows, 'id');
        $recordIds = array_values(array_unique(array_filter(array_map(static fn(array $row): int => absint($row['record_id'] ?? 0), $versionRows))));
        foreach ($submissionRows as $row) {
            $rid = absint($row['record_id'] ?? 0);
            if ($rid > 0) $recordIds[] = $rid;
        }

        // Canonical records can survive an old/manual submission deletion. Add
        // records whose current summary still points at the operative or route,
        // then rebuild them after the scoped history is removed.
        $recordParts = ['fr.last_user_id=%d'];
        $recordArgs = [$userId];
        if ($routeIds) $recordParts[] = 'fr.latest_route_id IN (' . self::idList($routeIds) . ')';
        if ($stopIds) $recordParts[] = 'fr.latest_route_stop_id IN (' . self::idList($stopIds) . ')';
        $recordWhere = ['(' . implode(' OR ', $recordParts) . ')'];
        self::appendDateRange($recordWhere, $recordArgs, 'DATE(fr.last_submitted_at)', $range);
        $recordIds = array_merge($recordIds, self::columnIds($wpdb->get_col($wpdb->prepare(
            "SELECT fr.id FROM {$px}form_records fr WHERE " . implode(' AND ', $recordWhere) . ' ORDER BY fr.id ASC',
            ...$recordArgs
        )) ?: []));
        $recordIds = self::columnIds($recordIds);

        $answerCount = $submissionIds ? (int)$wpdb->get_var("SELECT COUNT(*) FROM {$px}form_submission_answers WHERE submission_id IN (" . self::idList($submissionIds) . ')') : 0;
        $recordValueIds = [];
        if ($versionIds) {
            $recordValueIds = self::columnIds($wpdb->get_col("SELECT id FROM {$px}form_record_values WHERE version_id IN (" . self::idList($versionIds) . ')') ?: []);
        }
        if ($recordIds) {
            $orphanValueIds = self::columnIds($wpdb->get_col(
                "SELECT rv.id FROM {$px}form_record_values rv LEFT JOIN {$px}form_record_versions v ON v.id=rv.version_id WHERE rv.record_id IN (" . self::idList($recordIds) . ') AND v.id IS NULL'
            ) ?: []);
            $recordValueIds = self::columnIds(array_merge($recordValueIds, $orphanValueIds));
        }
        $valueCount = count($recordValueIds);

        $eventParts = ['e.user_id=%d'];
        $eventArgs = [$userId];
        if ($stopIds) $eventParts[] = 'e.route_stop_id IN (' . self::idList($stopIds) . ')';
        $eventWhere = ['(' . implode(' OR ', $eventParts) . ')'];
        self::appendDateRange($eventWhere, $eventArgs, 'DATE(e.created_at)', $range);
        $eventIds = self::columnIds($wpdb->get_col($wpdb->prepare(
            "SELECT e.id FROM {$px}events e WHERE " . implode(' AND ', $eventWhere) . ' ORDER BY e.id ASC',
            ...$eventArgs
        )) ?: []);

        // Route assignments attached to routes being removed are children of the
        // route. We also remove the selected user's assignment on a same-period
        // route without deleting a route owned by somebody else.
        $routeAssignmentRows = [];
        $assignmentIds = [];
        if ($routeIds) {
            $routeAssignmentRows = $wpdb->get_results("SELECT id,route_id,user_id FROM {$px}assignments WHERE route_id IN (" . self::idList($routeIds) . ') ORDER BY id ASC', ARRAY_A) ?: [];
            $assignmentIds = self::ids($routeAssignmentRows, 'id');
        }
        $otherAssignmentWhere = ['a.user_id=%d'];
        $otherAssignmentArgs = [$userId];
        self::appendDateRange($otherAssignmentWhere, $otherAssignmentArgs, 'r.date', $range);
        if ($routeIds) $otherAssignmentWhere[] = 'a.route_id NOT IN (' . self::idList($routeIds) . ')';
        $otherAssignmentRows = $wpdb->get_results($wpdb->prepare(
            "SELECT a.id,a.route_id,a.user_id FROM {$px}assignments a INNER JOIN {$px}routes r ON r.id=a.route_id WHERE " . implode(' AND ', $otherAssignmentWhere) . ' ORDER BY a.id ASC',
            ...$otherAssignmentArgs
        ), ARRAY_A) ?: [];
        $orphanAssignmentWhere = ['a.user_id=%d', 'r.id IS NULL'];
        $orphanAssignmentArgs = [$userId];
        self::appendDateRange($orphanAssignmentWhere, $orphanAssignmentArgs, 'DATE(a.created_at)', $range);
        $orphanAssignmentRows = $wpdb->get_results($wpdb->prepare(
            "SELECT a.id,a.route_id,a.user_id FROM {$px}assignments a LEFT JOIN {$px}routes r ON r.id=a.route_id WHERE " . implode(' AND ', $orphanAssignmentWhere) . ' ORDER BY a.id ASC',
            ...$orphanAssignmentArgs
        ), ARRAY_A) ?: [];
        $otherAssignmentRows = array_merge($otherAssignmentRows, $orphanAssignmentRows);
        $otherAssignmentIds = self::ids($otherAssignmentRows, 'id');
        $assignmentIds = array_values(array_unique(array_merge($assignmentIds, $otherAssignmentIds)));
        sort($assignmentIds, SORT_NUMERIC);

        // Safety gate: deleting a route owned by the target is allowed only when
        // the selected route does not contain activity attributable to another
        // operative. This prevents a test cleanup from erasing real work.
        $sharedRouteIds = [];
        $affectedUserIds = [$userId];
        foreach ($routeAssignmentRows as $row) {
            $assignedUserId = absint($row['user_id'] ?? 0);
            if ($assignedUserId > 0) $affectedUserIds[] = $assignedUserId;
            if ($assignedUserId > 0 && $assignedUserId !== $userId) $sharedRouteIds[] = absint($row['route_id'] ?? 0);
        }
        foreach ($otherAssignmentRows as $row) {
            $assignedUserId = absint($row['user_id'] ?? 0);
            if ($assignedUserId > 0) $affectedUserIds[] = $assignedUserId;
        }
        $sharedRouteIds = self::columnIds($sharedRouteIds);
        $affectedUserIds = self::columnIds($affectedUserIds);

        $draftRows = [];
        $draftFileRows = [];
        if (self::tableExists($px . 'form_drafts')) {
            $draftWhere = ['d.user_id=%d'];
            $draftArgs = [$userId];
            self::appendDateRange($draftWhere, $draftArgs, 'd.report_day', $range);
            $draftRows = $wpdb->get_results($wpdb->prepare("SELECT d.id,d.route_id,d.route_stop_id,d.location_id,d.report_day FROM {$px}form_drafts d WHERE " . implode(' AND ', $draftWhere) . ' ORDER BY d.id ASC', ...$draftArgs), ARRAY_A) ?: [];
        }
        if (self::tableExists($px . 'form_draft_files')) {
            $draftFileWhere = ['f.user_id=%d'];
            $draftFileArgs = [$userId];
            self::appendDateRange($draftFileWhere, $draftFileArgs, 'DATE(f.created_at)', $range);
            $draftFileRows = $wpdb->get_results($wpdb->prepare("SELECT f.id,f.draft_id,f.storage_path,f.file_size,f.created_at FROM {$px}form_draft_files f WHERE " . implode(' AND ', $draftFileWhere) . ' ORDER BY f.id ASC', ...$draftFileArgs), ARRAY_A) ?: [];
        }

        $snapshotRows = [];
        if (($routeIds || $stopIds) && self::tableExists($px . 'route_location_snapshot')) {
            $snapshotParts = [];
            if ($routeIds) $snapshotParts[] = 'route_id IN (' . self::idList($routeIds) . ')';
            if ($stopIds) $snapshotParts[] = 'route_stop_id IN (' . self::idList($stopIds) . ')';
            $snapshotRows = $wpdb->get_results("SELECT id,route_id,route_stop_id,location_id FROM {$px}route_location_snapshot WHERE (" . implode(' OR ', $snapshotParts) . ') ORDER BY id ASC', ARRAY_A) ?: [];
        }

        $shoppingRows = [];
        if (self::tableExists($px . 'shopping_submissions')) {
            $shoppingWhere = ['ss.user_id=%d'];
            $shoppingArgs = [$userId];
            self::appendDateRange($shoppingWhere, $shoppingArgs, 'DATE(ss.submitted_at)', $range);
            $shoppingRows = $wpdb->get_results($wpdb->prepare("SELECT ss.id,ss.assignment_id,ss.submitted_at FROM {$px}shopping_submissions ss WHERE " . implode(' AND ', $shoppingWhere) . ' ORDER BY ss.id ASC', ...$shoppingArgs), ARRAY_A) ?: [];
        }

        $expensesRetained = 0;
        if (self::tableExists($px . 'expenses')) {
            $expenseWhere = ['user_id=%d'];
            $expenseArgs = [$userId];
            self::appendDateRange($expenseWhere, $expenseArgs, 'expense_date', $range);
            $expensesRetained = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$px}expenses WHERE " . implode(' AND ', $expenseWhere), ...$expenseArgs));
        }

        $foreignSubmissionIds = [];
        foreach ($submissionRows as $row) {
            $submissionUserId = absint($row['user_id'] ?? 0);
            if ($submissionUserId > 0 && $submissionUserId !== $userId) $foreignSubmissionIds[] = absint($row['id'] ?? 0);
        }
        $foreignSubmissionIds = self::columnIds($foreignSubmissionIds);

        $foreignVersionIds = [];
        foreach ($versionRows as $row) {
            $versionUserId = absint($row['user_id'] ?? 0);
            $ownerUserId = absint($row['owner_user_id'] ?? 0);
            $hasTarget = $versionUserId === $userId || $ownerUserId === $userId;
            $hasForeign = ($versionUserId > 0 && $versionUserId !== $userId) || ($ownerUserId > 0 && $ownerUserId !== $userId);
            if (!$hasTarget && $hasForeign) $foreignVersionIds[] = absint($row['id'] ?? 0);
        }
        $foreignVersionIds = self::columnIds($foreignVersionIds);

        $azure = self::azureImpact($userId, $submissionIds, $routeIds, $stopIds, $range);
        $locations = array_values(array_unique(array_filter(array_map(static fn(array $row): int => absint($row['location_id'] ?? 0), array_merge($stopRows, $submissionRows)))));
        sort($locations, SORT_NUMERIC);
        $affectedUserIds = self::affectedUsersForLocations($locations, $affectedUserIds);
        $risk = [
            'shared_routes'=>count($sharedRouteIds),
            'shared_route_ids'=>$sharedRouteIds,
            'foreign_submissions'=>count($foreignSubmissionIds),
            'foreign_submission_ids'=>$foreignSubmissionIds,
            'foreign_versions'=>count($foreignVersionIds),
            'foreign_version_ids'=>$foreignVersionIds,
        ];
        $riskBlocked = !empty($sharedRouteIds) || !empty($foreignSubmissionIds) || !empty($foreignVersionIds);

        $counts = [
            'routes'=>count($routeIds),
            'route_stops'=>count($stopIds),
            'route_assignments'=>count($assignmentIds),
            'submissions'=>count($submissionIds),
            'answers'=>$answerCount,
            'record_versions'=>count($versionIds),
            'record_values'=>$valueCount,
            'records_rebuilt'=>count($recordIds),
            'events'=>count($eventIds),
            'drafts'=>count($draftRows),
            'draft_files'=>count($draftFileRows),
            'route_snapshots'=>count($snapshotRows),
            'shopping_submissions'=>count($shoppingRows),
            'expenses_retained'=>$expensesRetained,
            'azure_synced_submissions'=>(int)($azure['synced_submissions'] ?? 0),
            'azure_completed_jobs'=>(int)($azure['completed_jobs'] ?? 0),
        ];
        $destructiveTotal = array_sum(array_intersect_key($counts, array_flip(['routes','route_stops','route_assignments','submissions','answers','record_versions','record_values','events','drafts','draft_files','route_snapshots','shopping_submissions'])));

        $scope = [
            'user_id'=>$userId,
            'date_from'=>$range['from'],
            'date_to'=>$range['to'],
            'all_dates'=>$range['from'] === '' && $range['to'] === '',
        ];
        $ids = [
            'routes'=>$routeIds,
            'stops'=>$stopIds,
            'assignments'=>$assignmentIds,
            'submissions'=>$submissionIds,
            'versions'=>$versionIds,
            'record_values'=>$recordValueIds,
            'records'=>$recordIds,
            'events'=>$eventIds,
            'drafts'=>self::ids($draftRows, 'id'),
            'draft_files'=>self::ids($draftFileRows, 'id'),
            'route_snapshots'=>self::ids($snapshotRows, 'id'),
            'shopping_submissions'=>self::ids($shoppingRows, 'id'),
            'shopping_assignments'=>array_values(array_unique(array_filter(array_map(static fn(array $row): int => absint($row['assignment_id'] ?? 0), $shoppingRows)))),
            'locations'=>$locations,
            'affected_users'=>$affectedUserIds,
        ];
        foreach ($ids as &$set) { sort($set, SORT_NUMERIC); }
        unset($set);

        $capacityBlocked = $routeOverflow || $submissionOverflow || $versionOverflow;
        $blocked = $capacityBlocked || $riskBlocked;
        $blockReason = '';
        if ($capacityBlocked) {
            $blockReason = 'O volume excede o limite de segurança. Usa um intervalo de datas menor.';
        } elseif ($riskBlocked) {
            $blockReason = 'Foram detetados dados de outros utilizadores dentro das rotas selecionadas. A purga foi bloqueada para proteger a operação real.';
        }
        $signature = hash('sha256', wp_json_encode(['scope'=>$scope,'ids'=>$ids,'counts'=>$counts,'risk'=>$risk], JSON_UNESCAPED_SLASHES));
        return [
            'ok'=>!$blocked,
            'blocked'=>$blocked,
            'block_reason'=>$blockReason,
            'service_version'=>self::VERSION,
            'scope'=>$scope,
            'user'=>self::safeUser($userId),
            'counts'=>$counts,
            'destructive_total'=>$destructiveTotal,
            'ids'=>$ids,
            'draft_file_rows'=>$draftFileRows,
            'azure'=>$azure,
            'risk'=>$risk,
            'signature'=>$signature,
            'preserved'=>[
                'wordpress_user'=>true,
                'clients_projects_locations'=>true,
                'campaign_and_project_assignments'=>true,
                'store_profiles'=>true,
                'expenses'=>true,
                'audit_security_cloud_ledgers'=>true,
            ],
        ];
    }

    public static function purge(int $userId, string $dateFrom, string $dateTo, string $expectedSignature = '') {
        global $wpdb;
        $preview = self::preview($userId, $dateFrom, $dateTo);
        if (is_wp_error($preview)) return $preview;
        if (!empty($preview['blocked'])) return new WP_Error('fieldflow_purge_blocked', (string)$preview['block_reason'], ['status'=>409]);
        if ($expectedSignature === '' || !hash_equals((string)$preview['signature'], $expectedSignature)) {
            return new WP_Error('fieldflow_purge_preview_changed', 'Os dados mudaram desde a pré-visualização. Faz uma nova simulação antes de purgar.', ['status'=>409]);
        }

        $px = $wpdb->prefix . 'routespro_';
        $ids = (array)$preview['ids'];
        $fileRows = (array)($preview['draft_file_rows'] ?? []);
        $result = ['deleted'=>[], 'rebuilt'=>[], 'azure'=>(array)$preview['azure']];

        if ($wpdb->query('START TRANSACTION') === false) {
            return new WP_Error('fieldflow_purge_transaction', 'Não foi possível iniciar a transação de purga.', ['status'=>500]);
        }
        try {
            $result['deleted']['events'] = self::deleteIds($px . 'events', 'id', $ids['events'] ?? []);

            // Draft database rows are transactional. Physical files are unlinked
            // only after COMMIT so a rollback never leaves a half-applied purge.
            $result['deleted']['draft_files'] = self::deleteIds($px . 'form_draft_files', 'id', $ids['draft_files'] ?? []);
            $result['deleted']['drafts'] = self::deleteIds($px . 'form_drafts', 'id', $ids['drafts'] ?? []);
            $result['deleted']['route_snapshots'] = self::deleteIds($px . 'route_location_snapshot', 'id', $ids['route_snapshots'] ?? []);

            if (!empty($ids['shopping_submissions']) && self::tableExists($px . 'shopping_submissions')) {
                $result['deleted']['shopping_submissions'] = self::deleteIds($px . 'shopping_submissions', 'id', $ids['shopping_submissions']);
                if (!empty($ids['shopping_assignments']) && self::tableExists($px . 'shopping_assignments')) {
                    foreach ((array)$ids['shopping_assignments'] as $assignmentId) {
                        $latest = (int)$wpdb->get_var($wpdb->prepare("SELECT id FROM {$px}shopping_submissions WHERE assignment_id=%d ORDER BY submitted_at DESC,id DESC LIMIT 1", $assignmentId));
                        $wpdb->update($px . 'shopping_assignments', [
                            'last_submission_id'=>$latest ?: null,
                            'status'=>$latest ? 'submitted' : 'pending',
                            'submitted_at'=>$latest ? $wpdb->get_var($wpdb->prepare("SELECT submitted_at FROM {$px}shopping_submissions WHERE id=%d", $latest)) : null,
                        ], ['id'=>$assignmentId], ['%d','%s','%s'], ['%d']);
                    }
                }
            } else {
                $result['deleted']['shopping_submissions'] = 0;
            }

            $result['deleted']['answers'] = self::deleteWhereIn($px . 'form_submission_answers', 'submission_id', $ids['submissions'] ?? []);
            $result['deleted']['record_values'] = self::deleteIds($px . 'form_record_values', 'id', $ids['record_values'] ?? []);
            $result['deleted']['record_versions'] = self::deleteIds($px . 'form_record_versions', 'id', $ids['versions'] ?? []);
            $result['deleted']['submissions'] = self::deleteIds($px . 'form_submissions', 'id', $ids['submissions'] ?? []);

            if (!empty($ids['records'])) {
                $rebuilt = RecordService::rebuild_records((array)$ids['records']);
                if (is_wp_error($rebuilt)) throw new \RuntimeException($rebuilt->get_error_message());
                $result['rebuilt'] = $rebuilt;
            }

            $result['deleted']['route_assignments'] = self::deleteIds($px . 'assignments', 'id', $ids['assignments'] ?? []);
            $result['deleted']['route_stops'] = self::deleteIds($px . 'route_stops', 'id', $ids['stops'] ?? []);
            $result['deleted']['routes'] = self::deleteIds($px . 'routes', 'id', $ids['routes'] ?? []);

            if ($wpdb->query('COMMIT') === false) throw new \RuntimeException('Não foi possível confirmar a transação.');
        } catch (\Throwable $error) {
            $wpdb->query('ROLLBACK');
            return new WP_Error('fieldflow_purge_failed', 'A purga foi revertida. ' . $error->getMessage(), ['status'=>500]);
        }

        $physicalFilesRemoved = 0;
        $physicalFilesSkipped = 0;
        foreach ($fileRows as $fileRow) {
            $path = (string)($fileRow['storage_path'] ?? '');
            if ($path === '') continue;
            if (self::safeUnlinkDraftFile($path)) $physicalFilesRemoved++;
            elseif (file_exists($path)) $physicalFilesSkipped++;
        }
        $result['deleted']['physical_draft_files'] = $physicalFilesRemoved;
        if ($physicalFilesSkipped > 0) $result['deleted']['physical_draft_files_skipped'] = $physicalFilesSkipped;

        foreach ((array)($ids['affected_users'] ?? [$userId]) as $affectedUserId) {
            $affectedUserId = absint($affectedUserId);
            if ($affectedUserId <= 0) continue;
            Permissions::clear_scope_cache($affectedUserId);
            if (class_exists(RouteOptimizationService::class)) RouteOptimizationService::invalidateUserRouteCache($affectedUserId);
        }
        if (class_exists('\\RoutesPro\\Stores\\StoreProfileService')) {
            foreach ((array)($ids['locations'] ?? []) as $locationId) {
                if (method_exists('\\RoutesPro\\Stores\\StoreProfileService', 'invalidateCache')) {
                    \RoutesPro\Stores\StoreProfileService::invalidateCache((int)$locationId);
                }
            }
        }

        $summary = [
            'service_version'=>self::VERSION,
            'scope'=>$preview['scope'],
            'target_user'=>$preview['user'],
            'preview_counts'=>$preview['counts'],
            'deleted'=>$result['deleted'],
            'rebuilt'=>$result['rebuilt'],
            'azure'=>$result['azure'],
            'signature'=>$preview['signature'],
        ];
        self::recordRun('apply', $summary);
        AuditLog::record('user.operational_purge.executed', 'user', $userId, $preview['counts'], $result['deleted'], [
            'actor_user_id'=>get_current_user_id(),
            'source'=>AuditLog::source(),
        ], [
            'scope'=>$preview['scope'],
            'signature'=>$preview['signature'],
            'azure_cleanup_required'=>!empty($preview['azure']['cleanup_required']),
        ]);

        return [
            'ok'=>true,
            'scope'=>$preview['scope'],
            'user'=>$preview['user'],
            'preview_counts'=>$preview['counts'],
            'deleted'=>$result['deleted'],
            'rebuilt'=>$result['rebuilt'],
            'azure'=>$result['azure'],
            'signature'=>$preview['signature'],
        ];
    }

    public static function recordPreview(array $preview): void {
        if (empty($preview['user']['id'])) return;
        self::recordRun('preview', [
            'service_version'=>self::VERSION,
            'scope'=>$preview['scope'] ?? [],
            'target_user'=>$preview['user'] ?? [],
            'counts'=>$preview['counts'] ?? [],
            'azure'=>$preview['azure'] ?? [],
            'signature'=>$preview['signature'] ?? '',
        ]);
        AuditLog::record('user.operational_purge.previewed', 'user', (int)$preview['user']['id'], null, $preview['counts'] ?? [], [
            'actor_user_id'=>get_current_user_id(),
            'source'=>AuditLog::source(),
        ], ['scope'=>$preview['scope'] ?? [], 'signature'=>$preview['signature'] ?? '']);
    }

    private static function azureImpact(int $userId, array $submissionIds, array $routeIds, array $stopIds, array $range): array {
        global $wpdb;
        $out = [
            'synced_submissions'=>0,
            'completed_jobs'=>0,
            'completed_connector_jobs'=>0,
            'cleanup_required'=>false,
            'submission_ids'=>[],
            'event_uuids'=>[],
        ];
        $px = $wpdb->prefix . 'routespro_';
        if (!self::tableExists($px . 'core_events')) return $out;

        // Search by more than the live submissions table. A submission may have
        // been manually deleted before this purge, while its immutable Cloud
        // event and remote materialisation still exist.
        $parts = ['ce.actor_user_id=%d'];
        $args = [$userId];
        if ($submissionIds) $parts[] = 'ce.submission_id IN (' . self::idList($submissionIds) . ')';
        if ($routeIds) $parts[] = 'ce.route_id IN (' . self::idList($routeIds) . ')';
        if ($stopIds) $parts[] = 'ce.route_stop_id IN (' . self::idList($stopIds) . ')';
        $where = ["ce.event_name IN ('submission.created','submission.updated')", '(' . implode(' OR ', $parts) . ')'];
        self::appendDateRange($where, $args, 'DATE(ce.created_at)', $range);
        $eventRows = $wpdb->get_results($wpdb->prepare(
            "SELECT ce.event_uuid,ce.submission_id,ce.actor_user_id,ce.route_id,ce.route_stop_id,ce.created_at FROM {$px}core_events ce WHERE " . implode(' AND ', $where) . ' ORDER BY ce.id ASC',
            ...$args
        ), ARRAY_A) ?: [];
        if (!$eventRows) return $out;

        $eventUuids = array_values(array_unique(array_filter(array_map(static fn(array $r): string => sanitize_text_field((string)($r['event_uuid'] ?? '')), $eventRows))));
        if (!$eventUuids) return $out;
        $quoted = "'" . implode("','", array_map('esc_sql', $eventUuids)) . "'";
        $completedUuids = [];
        if (self::tableExists($px . 'cloud_sync_jobs')) {
            $rows = $wpdb->get_col("SELECT event_uuid FROM {$px}cloud_sync_jobs WHERE event_uuid IN ({$quoted}) AND status='completed'") ?: [];
            $completedUuids = array_merge($completedUuids, array_map('strval', $rows));
            $out['completed_jobs'] = count($rows);
        }
        if (self::tableExists($px . 'cloud_connector_jobs')) {
            $rows = $wpdb->get_col("SELECT event_uuid FROM {$px}cloud_connector_jobs WHERE event_uuid IN ({$quoted}) AND status='completed'") ?: [];
            $completedUuids = array_merge($completedUuids, array_map('strval', $rows));
            $out['completed_connector_jobs'] = count($rows);
        }
        $completedUuids = array_values(array_unique($completedUuids));
        if ($completedUuids) {
            $set = array_fill_keys($completedUuids, true);
            $synced = [];
            $matchedEvents = [];
            foreach ($eventRows as $row) {
                $uuid = (string)($row['event_uuid'] ?? '');
                if (empty($set[$uuid])) continue;
                $matchedEvents[] = $uuid;
                $submissionId = absint($row['submission_id'] ?? 0);
                if ($submissionId > 0) $synced[] = $submissionId;
            }
            $synced = array_values(array_unique(array_filter($synced)));
            sort($synced, SORT_NUMERIC);
            $out['synced_submissions'] = count($synced);
            $out['submission_ids'] = $synced;
            $out['event_uuids'] = array_values(array_unique($matchedEvents));
            $out['cleanup_required'] = !empty($matchedEvents);
        }
        return $out;
    }

    private static function recordRun(string $mode, array $payload): void {
        global $wpdb;
        $table = $wpdb->prefix . 'routespro_reconciliation_runs';
        if (!self::tableExists($table)) return;
        $now = current_time('mysql');
        $wpdb->insert($table, [
            'run_type'=>'user_operational_purge',
            'run_mode'=>$mode === 'apply' ? 'apply' : 'preview',
            'status'=>$mode === 'apply' ? 'completed' : 'previewed',
            'initiated_by'=>get_current_user_id() ?: null,
            'summary_json'=>wp_json_encode([
                'target_user'=>$payload['target_user'] ?? [],
                'scope'=>$payload['scope'] ?? [],
                'counts'=>$payload['counts'] ?? ($payload['preview_counts'] ?? []),
                'deleted'=>$payload['deleted'] ?? [],
                'azure_cleanup_required'=>!empty($payload['azure']['cleanup_required']),
            ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES),
            'details_json'=>wp_json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES),
            'started_at'=>$now,
            'completed_at'=>$now,
            'created_at'=>$now,
        ], ['%s','%s','%s','%d','%s','%s','%s','%s','%s']);
    }

    private static function deleteIds(string $table, string $column, array $ids): int {
        global $wpdb;
        $ids = self::columnIds($ids);
        if (!$ids || !self::tableExists($table)) return 0;
        $result = $wpdb->query("DELETE FROM {$table} WHERE {$column} IN (" . self::idList($ids) . ')');
        if ($result === false) throw new \RuntimeException($wpdb->last_error ?: 'Falha ao remover registos em ' . $table . '.');
        return (int)$result;
    }

    private static function deleteWhereIn(string $table, string $column, array $ids): int {
        return self::deleteIds($table, $column, $ids);
    }

    private static function affectedUsersForLocations(array $locationIds, array $seed): array {
        global $wpdb;
        $users = self::columnIds($seed);
        $locationIds = self::columnIds($locationIds);
        if (!$locationIds) return $users;
        $px = $wpdb->prefix . 'routespro_';
        $in = self::idList($locationIds);

        if (self::tableExists($px . 'campaign_locations')) {
            $rows = $wpdb->get_col("SELECT DISTINCT assigned_to FROM {$px}campaign_locations WHERE location_id IN ({$in}) AND assigned_to IS NOT NULL AND assigned_to>0") ?: [];
            $users = array_merge($users, self::columnIds($rows));
        }
        if (self::tableExists($px . 'route_stops') && self::tableExists($px . 'routes')) {
            $rows = $wpdb->get_col("SELECT DISTINCT r.owner_user_id FROM {$px}routes r INNER JOIN {$px}route_stops rs ON rs.route_id=r.id WHERE rs.location_id IN ({$in}) AND r.owner_user_id IS NOT NULL AND r.owner_user_id>0") ?: [];
            $users = array_merge($users, self::columnIds($rows));
        }
        if (self::tableExists($px . 'route_stops') && self::tableExists($px . 'assignments')) {
            $rows = $wpdb->get_col("SELECT DISTINCT a.user_id FROM {$px}assignments a INNER JOIN {$px}route_stops rs ON rs.route_id=a.route_id WHERE rs.location_id IN ({$in}) AND a.user_id>0") ?: [];
            $users = array_merge($users, self::columnIds($rows));
        }
        return self::columnIds($users);
    }

    private static function safeUnlinkDraftFile(string $path): bool {
        $real = realpath($path);
        if ($real === false || !is_file($real)) return false;
        $uploads = wp_upload_dir(null, false);
        $base = is_array($uploads) ? (string)($uploads['basedir'] ?? '') : '';
        $baseReal = $base !== '' ? realpath($base) : false;
        if ($baseReal === false) return false;
        $basePrefix = rtrim(str_replace('\\', '/', $baseReal), '/') . '/';
        $fileReal = str_replace('\\', '/', $real);
        if (strpos($fileReal, $basePrefix) !== 0) return false;
        return @unlink($real);
    }

    private static function tableExists(string $table): bool {
        global $wpdb;
        return (string)$wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) === $table;
    }

    private static function normaliseRange(string $dateFrom, string $dateTo) {
        $from = self::date($dateFrom);
        $to = self::date($dateTo);
        if ($dateFrom !== '' && $from === '') return new WP_Error('fieldflow_purge_date_invalid', 'Data inicial inválida.', ['status'=>400]);
        if ($dateTo !== '' && $to === '') return new WP_Error('fieldflow_purge_date_invalid', 'Data final inválida.', ['status'=>400]);
        if ($from !== '' && $to !== '' && $from > $to) return new WP_Error('fieldflow_purge_date_range_invalid', 'A data final não pode ser anterior à data inicial.', ['status'=>400]);
        return ['from'=>$from,'to'=>$to];
    }

    private static function date(string $value): string {
        $value = trim($value);
        if ($value === '') return '';
        $dt = \DateTimeImmutable::createFromFormat('!Y-m-d', $value);
        return $dt && $dt->format('Y-m-d') === $value ? $value : '';
    }

    private static function appendDateRange(array &$where, array &$args, string $expr, array $range): void {
        if ($range['from'] !== '') { $where[] = "{$expr}>=%s"; $args[] = $range['from']; }
        if ($range['to'] !== '') { $where[] = "{$expr}<=%s"; $args[] = $range['to']; }
    }

    private static function ids(array $rows, string $key): array {
        return self::columnIds(array_map(static fn(array $row): int => absint($row[$key] ?? 0), $rows));
    }

    private static function columnIds(array $ids): array {
        $ids = array_values(array_unique(array_filter(array_map('absint', $ids))));
        sort($ids, SORT_NUMERIC);
        return $ids;
    }

    private static function idList(array $ids): string {
        return implode(',', self::columnIds($ids));
    }

    private static function safeUser(int $userId): array {
        $user = get_userdata($userId);
        return [
            'id'=>$userId,
            'login'=>$user ? (string)$user->user_login : '',
            'name'=>$user ? (string)$user->display_name : '',
            'email'=>$user ? (string)$user->user_email : '',
        ];
    }
}
